//! Cargo-driven `ctfmon.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is ctfmon-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wWinMainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wWinMainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wWinMainCRTStartup"),
        o => panic!("ctfmon-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:uuid", "engine:c:cicero", "import:msctf", "import:msutb", "import:advapi32", "import:shell32", "import:user32", "import:msvcrt", "import:kernel32", "import:gdi32", "import:imm32", "import:comctl32", "import:ntdll", "engine:oldnames", "engine:delayimp_rust"],
        "x86_64" => &["body", "engine:uuid", "engine:c:cicero", "import:msctf", "import:msutb", "import:advapi32", "import:shell32", "import:user32", "import:msvcrt", "import:kernel32", "import:gdi32", "import:imm32", "import:comctl32", "import:ntdll", "engine:oldnames", "engine:delayimp_rust"],
        "aarch64" => &["body", "engine:uuid", "engine:c:cicero", "import:msctf", "import:msutb", "import:advapi32", "import:shell32", "import:user32", "import:msvcrt", "import:kernel32", "import:gdi32", "import:imm32", "import:comctl32", "import:ntdll", "engine:oldnames", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/ctf/ctfmon",
        "base/ctf/ctfmon",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .rust_staticlib("ctfmon-rust")
        .c_from_compile_db("ctfmon_shims", &["base/ctf/ctfmon/rust_cohab_stub.cpp"])
        .rc("base/ctf/ctfmon/ctfmon.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("base/ctf/msctf/msctf.spec", "msctf.dll", "msctf")
        .import_lib("base/ctf/msutb/msutb.spec", "msutb.dll", "msutb")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .delay_import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .delay_import_lib("win32ss/user/imm32/imm32.spec", "imm32.dll", "imm32")
        .delay_import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
